import { useParams } from "react-router-dom";
import {
  Carousel,
  Typography,
  Transition,
  PageGap,
  PageTemplate,
  HeroImage,
} from "../../../components";
import useFetch from "../../../hooks/useFetch";
import { API_DOMAIN } from "../../../utils/constants";

import styles from "./ShowcaseDetail.module.css";

function ProjectDetail() {
  const params = useParams();
  const id = params.id;
  const { data, isLoading } = useFetch({
    url: API_DOMAIN + "?type=projectInfo&index=" + id,
  });
  return (
    <Transition isLoading={isLoading || !data}>
      <PageTemplate>
        {data && (
          <PageGap>
            <HeroImage
              heading={data[0].name}
              src={data[0].coverPic}
              subheading={data[0].tagline}
            />
            <Typography variant="body">{data[0].description}</Typography>
            <div className={styles["gallery-box"]}>
              <Typography variant="smallHeading">Gallery</Typography>
              {data[0].photos && <Carousel images={data[0].photos} />}
            </div>
          </PageGap>
        )}
      </PageTemplate>
    </Transition>
  );
}

export default ProjectDetail;
